<script setup lang="ts">import {computed,ref} from 'vue';import AppShell from '@/components/zs/AppShell.vue';import PageHeader from '@/components/zs/PageHeader.vue';import Panel from '@/components/zs/Panel.vue';import DataTable from '@/components/zs/DataTable.vue';import StatusBadge from '@/components/zs/StatusBadge.vue';import ZButton from '@/components/zs/ZButton.vue';import {useCrmData} from '@/composables/useCrmData';import {showToast} from '@/composables/useToast';import {setPageMeta} from '@/lib/page-meta';setPageMeta('CRM Tasks','Manage sales follow-ups and customer actions.');function notify(message:string){showToast('Task updated',message)}const d=useCrmData(),done=ref<string[]>([]);const rows=computed(()=>(d.tasks.data.value??[]).map(x=>done.value.includes(x.id)?{...x,status:'Completed' as const}:x));const columns=[{key:'title',header:'Task'},{key:'relatedTo',header:'Related to'},{key:'owner',header:'Owner'},{key:'due',header:'Due'},{key:'priority',header:'Priority'},{key:'status',header:'Status'},{key:'actions',header:'',align:'right' as const}];</script>
<template><AppShell><PageHeader title="Tasks" :description="`${rows.filter(x=>x.status!=='Completed').length} open actions`"><template #actions><ZButton @click="notify('Task form opened in preview mode.')">New task</ZButton></template></PageHeader><Panel><DataTable :columns="columns" :rows="rows" :min-width="900"><template #title="{row}"><span class="font-medium text-content">{{row.title}}</span></template><template #priority="{row}"><StatusBadge :status="row.priority"/></template><template #status="{row}"><StatusBadge :status="row.status"/></template><template #actions="{row}"><ZButton variant="ghost" :disabled="row.status==='Completed'" @click="done.push(row.id)">Complete</ZButton></template></DataTable></Panel></AppShell></template>
